37	void WriteBufferFromAzureBlobStorage::finalizeImpl()
38	{
39	    if (attributes.has_value())
40	    {
41	        auto blob_client = blob_container_client->GetBlobClient(blob_path);
42	        Azure::Storage::Metadata metadata;
43	        for (const auto & [key, value] : *attributes)
44	            metadata[key] = value;
45	        blob_client.SetMetadata(metadata);
46	    }
47	
48	    const size_t max_tries = 3;
49	    for (size_t i = 0; i < max_tries; ++i)
50	    {
51	        try
52	        {
53	            next();
54	            break;
55	        }
56	        catch (const Azure::Core::RequestFailedException & e)
57	        {
58	            if (i == max_tries - 1)
59	                throw;
60	            LOG_INFO(&Poco::Logger::get("WriteBufferFromAzureBlobStorage"),
61	                     "Exception caught during finalizing azure storage write at attempt {}: {}", i + 1, e.Message);
62	        }
63	    }
64	}
65	
66	void WriteBufferFromAzureBlobStorage::nextImpl()
67	{
68	    if (!offset())
69	        return;
70	
71	    auto * buffer_begin = working_buffer.begin();
72	    auto len = offset();
73	    auto block_blob_client = blob_container_client->GetBlockBlobClient(blob_path);
74	
75	    size_t read = 0;
76	    std::vector<std::string> block_ids;
77	    while (read < len)
78	    {
79	        auto part_len = std::min(len - read, max_single_part_upload_size);
80	
81	        auto block_id = getRandomASCIIString(64);
82	        block_ids.push_back(block_id);
83	
84	        Azure::Core::IO::MemoryBodyStream tmp_buffer(reinterpret_cast<uint8_t *>(buffer_begin + read), part_len);
85	        block_blob_client.StageBlock(block_id, tmp_buffer);
86	
87	        read += part_len;
88	    }
89	
90	    block_blob_client.CommitBlockList(block_ids);
91	
92	    if (write_settings.remote_throttler)
93	        write_settings.remote_throttler->add(read);
94	}
